    A terminal or code window: a title bar with three round marks, then the lines. A `command` line starts with the prompt, an `output` line is muted. Static: the typing animation belongs to the port (TypingText contract).
    Props (p): title, prompt, lines, className. *}
{var $v_title = ($p['title'] ?? null)}
{var $v_prompt = ($p['prompt'] ?? null)}
{var $v_lines = ($p['lines'] ?? null)}
{capture $c_7}
  {capture $c_2}
    {capture $c_1}
      {=ui_text($v_title)}
    {/capture}
    {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_1])|noescape}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex items-center border-b border-border px-4 py-2'], 'children' => $c_2])|noescape}
  {capture $c_6}
    {foreach ui_l($v_lines) as $v_line}
      {capture $c_5}
        {if ui_t(ui_eq(ui_get($v_line, ['kind']), 'command'))}
          {capture $c_3}
            {=ui_text($v_prompt)}
          {/capture}
          {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'select-none text-muted-foreground'], 'children' => $c_3])|noescape}
        {/if}
        {capture $c_4}
          {=ui_text(ui_get($v_line, ['text']))}
        {/capture}
        {=ui_include('ui/inline/inline.latte', ['p' => [], 'children' => $c_4])|noescape}
      {/capture}
      {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => ui_s(ui_cnv(['flex gap-2', (ui_t(ui_eq(ui_get($v_line, ['kind']), 'command')) ? 'text-foreground' : 'text-muted-foreground')])), 'Attrs' => ui_attrs(['data-kind', ui_get($v_line, ['kind'])])], 'children' => $c_5])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/list/list.latte', ['p' => ['Class' => 'm-0 flex list-none flex-col gap-2 p-4 font-mono text-sm'], 'children' => $c_6])|noescape}
{/capture}
{=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s(ui_cnv(['w-full overflow-hidden rounded bg-card text-left inset-ring inset-ring-border', ($p['className'] ?? '')])), 'Attrs' => ui_attrs(['role', 'group', 'aria-label', $v_title, 'data-slot', 'code-window'])], 'children' => $c_7])|noescape}
